-- Queer Atlas: verified queer and queer-friendly electronic events, Batch 3.
-- Countries: Germany, Belgium, Netherlands and Poland. Researched 2026-08-29.
-- Queer-led events are labelled as such. Broader electronic events are included
-- only with meaningful published inclusion, consent or safer-space evidence.
-- Source data contains no vibe_tags; UPDATE and INSERT force ARRAY[]::text[].

begin;

alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists ticket_url text;

with src as (
  select * from jsonb_to_recordset($qa_central_europe_batch3_events$
[
{"name":"CHROMA XXL – Offbeat Session","aliases":["CHROMA XXL OFFBEAT SESSION"],"city":"berlin","date":"2026-09-10","start_date":"2026-09-10","end_date":"2026-09-11","description":"CHROMA closes summer at ÆDEN from 23:00–08:00 with experimental and driving techno across its programme and an explicitly queer-friendly, anti-discrimination policy.","link":"https://ra.co/events/2509185","ticket_url":"https://ra.co/events/2509185","location":"ÆDEN, Schleusenufer 2, 10997 Berlin, Germany","lat":52.5015,"lng":13.4424,"vibe":"experimental-to-driving techno in an explicitly queer-friendly Berlin space","intel":{"entry_wait":"Advance and door tickets are listed at twenty euros; bring valid 18+ identification and arrive before the strongest late-night queue.","best_arrival":"Reach ÆDEN near 23:00 to explore the experimental stage and hear the complete build into the main techno programme.","crowd_mix":"Berlin techno regulars, queer dancers, international visitors and listeners seeking experimental sounds share the multi-stage session.","dress_code":"No mandatory look is published; intentional, movement-ready Berlin clubwear works better than formal or highly impractical clothing.","host_inclusivity":"CHROMA explicitly calls the event queer-friendly and rejects racism, transphobia, sexism, homophobia and every form of discrimination.","source_urls":["https://ra.co/events/2509185"],"research_status":"organiser_ticketing_and_inclusion_policy_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Baba Yaga: Slavic Witch Rave","aliases":["Baba Yaga Queer Slavic Witch Rave"],"city":"berlin","date":"2026-09-12","start_date":"2026-09-12","end_date":"2026-09-13","description":"Baba Yaga transforms Marmorbar from 22:00–08:00 with queer Slavic, Balkan, Caucasus and Central Asian techno, trance, drag, performance and moving image.","link":"https://ra.co/events/2507746","ticket_url":"https://ra.co/events/2507746","location":"Marmorbar, Vor dem Schlesischen Tor 3, 10997 Berlin, Germany","lat":52.5006,"lng":13.4417,"vibe":"queer Slavic cultural rave mixing techno, trance, drag and live performance","intel":{"entry_wait":"Advance entry is seventeen euros and the listed door price is twenty; book ahead and bring identification for the 18+ event.","best_arrival":"Arrive around 22:00 for the opening performances and full two-room programme rather than entering only for the late peak.","crowd_mix":"Queer artists and communities connected to Slavic, Balkan, Caucasus and Central Asian cultures are deliberately centred.","dress_code":"No compulsory outfit is stated; witchy, expressive or culturally thoughtful club looks suit the multidisciplinary format.","host_inclusivity":"The queer-led fundraiser supports Quarteera's mental-health group for parents of queer refugee and migrant children.","source_urls":["https://ra.co/events/2507746"],"research_status":"organiser_ticketing_and_community_fundraiser_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"PiepShow – SeptemberPiep","aliases":["SeptemberPiep 2026"],"city":"berlin","date":"2026-09-25","start_date":"2026-09-25","end_date":"2026-09-26","description":"PiepShow fills all five KitKatClub floors from 20:00–10:00 with queer techno, hard trance, house, disco, pop, drag, shibari and play areas.","link":"https://ra.co/events/2277053","ticket_url":"https://ra.co/events/2277053","location":"KitKatClub, Köpenicker Straße 76, 10179 Berlin, Germany","lat":52.5107,"lng":13.4162,"vibe":"colourful fourteen-hour queer techno rave with play spaces and five distinct floors","intel":{"entry_wait":"Tickets are sold only at the door, so arrive early, carry cash and valid ID, and allow time for the strict outfit assessment.","best_arrival":"Arrive near the 20:00 opening for the easiest door and the full fourteen-hour arc across all five rooms.","crowd_mix":"Queer Berliners, fetish communities, techno dancers, drag audiences and tolerant guests from across the identity spectrum attend.","dress_code":"Kinky, fetish, sporty, creative, sexy or costume looks are required; ordinary jeans and T-shirts are explicitly discouraged.","host_inclusivity":"PiepShow describes itself as a colourful queer techno rave for everyone who dances with tolerance, inside a consent-dependent adult format.","source_urls":["https://ra.co/events/2277053"],"research_status":"organiser_door_dress_and_programme_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"HustlaBall Berlin Weekend 2026","aliases":["HustlaBall Berlin 2026"],"city":"berlin","date":"2026-10-15","start_date":"2026-10-15","end_date":"2026-10-18","description":"HustlaBall's official weekend combines a welcome reception, gay adult-industry club night at KitKatClub and Saturday Subscribe event under a sex-positive, consensual framework.","link":"https://hustlaball.de/","ticket_url":"https://hustlaball.de/","location":"Galerie Newman, KitKatClub and Club AMT, Berlin, Germany","lat":52.5107,"lng":13.4162,"vibe":"international gay adult-industry weekend joining gritty techno, performance and connection","intel":{"entry_wait":"A three-event wristband is collected at Galerie Newman; advance weekend passes and valid adult identification are essential for entry.","best_arrival":"Attend Thursday's reception to collect the wristband, then follow each club's stated doors and leave time for strict Friday selection.","crowd_mix":"Gay men, adult performers, content creators, fans, fetish communities and international visitors form a specialised adult audience.","dress_code":"Friday and Saturday require strict fetish or intentional adult-club attire; ordinary streetwear is not suitable for this weekend.","host_inclusivity":"The organiser explicitly defines the weekend as sex-positive and consensual, but guests should assess the adult gay-focused format personally.","source_urls":["https://hustlaball.de/","https://hustlaball.de/djs"],"research_status":"official_dates_venues_ticket_model_and_consent_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Pornfilmfestival Berlin 2026","aliases":["21st Pornfilmfestival Berlin","PFFB 2026"],"city":"berlin","date":"2026-10-20","start_date":"2026-10-20","end_date":"2026-10-25","description":"Berlin's independent Pornfilmfestival returns for its twenty-first edition with queer, feminist and sex-positive cinema, discussion, performance and industry exchange.","link":"https://pornfilmfestivalberlin.de/en/","ticket_url":"https://pornfilmfestivalberlin.de/en/","location":"Moviemento, Babylon Kreuzberg, Colosseum and Kino Central, Berlin, Germany","lat":52.4934,"lng":13.4224,"vibe":"queer feminist sex-positive cinema festival combining art, politics and body discourse","intel":{"entry_wait":"Individual screenings and forums use separate tickets; book opening, limited-capacity and guest sessions when online sales begin on 1 October.","best_arrival":"Plan by cinema and reach each venue before its seating time, allowing travel between Kreuzberg, Mitte and Prenzlauer Berg.","crowd_mix":"Queer, trans, non-binary and sex-positive audiences, filmmakers, sex workers, educators and international visitors meet across formats.","dress_code":"There is no festival-wide dress code; everyday cinema clothing is appropriate, with expressive looks natural at parties and performances.","host_inclusivity":"The independent festival explicitly centres sexuality, feminism, gender diversity, body politics and an empowering approach to sex work.","source_urls":["https://pornfilmfestivalberlin.de/en/","https://www.visitberlin.de/de/event/21-pornfilmfestival-berlin"],"research_status":"official_dates_mission_and_venues_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Hamburg International Queer Film Festival 2026","aliases":["HIQFF 2026"],"city":"hamburg","date":"2026-10-13","start_date":"2026-10-13","end_date":"2026-10-18","description":"Germany's oldest queer film festival returns for its thirty-seventh edition across Kampnagel and five Hamburg cinemas with international LGBTQIA+ work and discussion.","link":"https://www.hamburg.de/kultur/festival/hamburg-international-queer-film-festival-382072","ticket_url":"https://www.hiqff.de/","location":"Kampnagel, Metropolis, Passage, 3001, B-Movie and Rineuto, Hamburg, Germany","lat":53.5723,"lng":10.0266,"vibe":"large community-connected queer film festival spanning arthouse cinema and discussion","intel":{"entry_wait":"Screenings have independent capacities and ticketing; reserve premieres and guest events once the complete festival programme is released.","best_arrival":"Use the final timetable and arrive before each cinema's seating time, allowing travel between the six confirmed venues.","crowd_mix":"Hamburg LGBTQIA+ communities, queer filmmakers, cinephiles, students and international festival visitors share the programme.","dress_code":"There is no appearance requirement; comfortable cinema clothing and autumn layers suit movement between venues.","host_inclusivity":"The festival is explicitly queer and maintains a close relationship with Hamburg's LGBTQIA+ communities and queer film culture.","source_urls":["https://www.hamburg.de/kultur/festival/hamburg-international-queer-film-festival-382072","https://www.hiqff.de/"],"research_status":"official_city_dates_and_venues_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"QFFM – Queer Film Festival Munich 2026","aliases":["QFFM 2026","11th Queer Film Festival Munich"],"city":"munich","date":"2026-10-16","start_date":"2026-10-16","end_date":"2026-10-23","description":"QFFM's eleventh edition presents international and regional queer cinema, panels, workshops and performances across Munich from 16–23 October.","link":"https://qffm.de/","ticket_url":"https://qffm.de/","location":"City Kino, Münchner Kammerspiele and partner venues, Munich, Germany","lat":48.1372,"lng":11.5655,"vibe":"independent queer cinema week joining screenings, debate, performance and networking","intel":{"entry_wait":"Events use individual tickets and capacities; the opening at Münchner Kammerspiele is separately ticketed and the detailed programme follows later.","best_arrival":"Reach each named cinema before seating and allow transfer time; arrive early for the opening reception and high-demand guest screenings.","crowd_mix":"Queer film audiences, local community representatives, filmmakers, curators, students and Munich culture-goers meet throughout the week.","dress_code":"No festival-wide code applies; everyday cinema wear is suitable and a polished look fits the opening reception.","host_inclusivity":"QFFM is an independent queer institution created to show cinema beyond heteronormative and homonormative frameworks.","source_urls":["https://qffm.de/","https://www.muenchner-kammerspiele.de/en/programm/52766-11-qffm"],"research_status":"official_dates_opening_and_mission_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Queer Literature Festival Munich 2026","aliases":["Queeres Literaturfestival München 2026","QLFM 2026"],"city":"munich","date":"2026-11-07","start_date":"2026-11-07","end_date":"2026-11-10","description":"Munich's Queer Literature Festival brings readings, workshops, conversations and contemporary LGBTQIA+ writing to Gasteig HP8 for four days.","link":"https://www.gasteig.de/festivals/queeres-literaturfestival-muenchen-2/","ticket_url":"https://www.gasteig.de/festivals/queeres-literaturfestival-muenchen-2/","location":"Gasteig HP8, Saal X, Hans-Preißinger-Straße 8, 81379 Munich, Germany","lat":48.1115,"lng":11.5534,"vibe":"intimate queer literary gathering centred on resistance, dialogue and shared reading","intel":{"entry_wait":"Readings and workshops have different capacities, so reserve participatory sessions and headline appearances through the venue programme.","best_arrival":"Reach Gasteig HP8 before each stated start, especially for workshops where late entry may disrupt the small-group format.","crowd_mix":"Queer readers, authors, poets, translators, students and community members gather around German-language contemporary and classic work.","dress_code":"No dress code applies; comfortable everyday clothing is appropriate for readings, workshops and extended conversations.","host_inclusivity":"The festival explicitly creates space for queer literature and challenges stereotypes while celebrating reading's community-building potential.","source_urls":["https://www.gasteig.de/festivals/queeres-literaturfestival-muenchen-2/"],"research_status":"official_venue_dates_and_scope_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"ColognePride 2027","aliases":["Cologne Pride 2027","CSD Cologne 2027"],"city":"cologne","date":"2027-06-11","start_date":"2027-06-11","end_date":"2027-07-04","description":"ColognePride has officially announced its 2027 season from 11 June–4 July, with the street festival 2–4 July and CSD demonstration on 4 July.","link":"https://www.colognepride.de/en/home","ticket_url":"https://www.colognepride.de/en/home","location":"City centre and Heumarkt, Cologne, Germany","lat":50.9375,"lng":6.9603,"vibe":"major German Pride season combining activism, community programming and vast public celebration","intel":{"entry_wait":"The public demonstration and street festival are open, while indoor parties and programme events may require separate advance tickets.","best_arrival":"Use the final Pride calendar; for the 4 July demonstration reach the assembly route early and expect central transport changes.","crowd_mix":"Cologne LGBTQIA+ communities, activists, organisations, families, international visitors, performers and allies form a very broad audience.","dress_code":"There is no festival-wide requirement; expressive Pride looks, weather protection and comfortable walking shoes are practical.","host_inclusivity":"ColognePride is the official queer organiser and combines political demands, community visibility and public celebration.","source_urls":["https://www.colognepride.de/en/home"],"research_status":"official_2027_full_dates_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"CLUB CVNT","aliases":["Club Cvnt Amsterdam"],"city":"amsterdam","date":"2026-09-11","start_date":"2026-09-11","end_date":"2026-09-12","description":"CLUB CVNT takes over Akhnaton from 22:00–05:30 with techno, electroclash and hyperpop in a women- and queer-centred Y2K party for girls, gays, theys and allies.","link":"https://ra.co/events/2509328","ticket_url":"https://ra.co/events/2509328","location":"Akhnaton, Nieuwezijds Kolk 25, 1012 PV Amsterdam, Netherlands","lat":52.3768,"lng":4.8931,"vibe":"women- and queer-centred Y2K club fantasy mixing techno, hyperpop and glamour","intel":{"entry_wait":"Advance tickets are listed at €18.50; bring valid identification for the 20+ door and book before travelling to the central venue.","best_arrival":"Arrive near 22:00 to enter before the Friday-night rush and hear the complete progression from glossy pop into harder club energy.","crowd_mix":"Women, queer and non-binary guests are centred, with respectful allies welcomed into the expressive party-girl revival.","dress_code":"Crop tops, glitter, glossy Y2K styling and deliberately overdressed looks are encouraged, though guests may also come exactly as they are.","host_inclusivity":"The organiser explicitly describes CLUB CVNT as women- and queer-centred and invites girls, gays, theys and allies to take up space.","source_urls":["https://ra.co/events/2509328"],"research_status":"organiser_ticketing_and_audience_focus_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"ADE – SPIELRAUM: 55 Hours","aliases":["SPIELRAUM 55 HOURS","ADE Spielraum 55 Hours"],"city":"amsterdam","date":"2026-10-23","start_date":"2026-10-23","end_date":"2026-10-26","description":"SPIELRAUM and queer-founded CLUB RAUM stage a continuous fifty-five-hour ADE weekender with house and techno from Friday 23:00 until Monday 06:00.","link":"https://ra.co/events/2478125","ticket_url":"https://ra.co/events/2478125","location":"CLUB RAUM, Humberweg 3, 1043 AC Amsterdam, Netherlands","lat":52.3852,"lng":4.8467,"vibe":"marathon queer techno institution balancing deep listening, intensity and collective freedom","intel":{"entry_wait":"The 21+ marathon uses timed and general ticket releases; buy early, carry ID and review re-entry and wristband rules before arrival.","best_arrival":"Choose an arrival around priority sets but allow a generous door window; a fifty-five-hour programme rewards pacing rather than chasing one peak.","crowd_mix":"Amsterdam's queer and trans club communities, international ADE visitors and serious house and techno listeners share the floor.","dress_code":"No single costume is required; expressive, practical clubwear and layers for rest periods suit the extended format.","host_inclusivity":"SPIELRAUM and CLUB RAUM are queer-founded spaces built around freedom of expression, community care and safer club culture.","source_urls":["https://ra.co/events/2478125","https://www.clubraum.nl/"],"research_status":"organiser_ticketing_and_queer_venue_context_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"RARA AVIS – ADE 2026","aliases":["RARA AVIS at Club NYX"],"city":"amsterdam","date":"2026-10-24","start_date":"2026-10-24","end_date":"2026-10-25","description":"RARA AVIS returns to Club NYX from 23:00–05:00 as ADE's colourful queer alternative to dark techno, mixing house, disco, hyperpop and bold performance.","link":"https://ra.co/events/2507060","ticket_url":"https://ra.co/events/2507060","location":"Club NYX, Reguliersdwarsstraat 42, 1017 BM Amsterdam, Netherlands","lat":52.3665,"lng":4.8921,"vibe":"colour-saturated queer ADE playground for club kids, techno clowns and fearless expression","intel":{"entry_wait":"Use the official advance ticket route and bring valid 18+ identification; ADE demand makes relying on remaining door capacity risky.","best_arrival":"Arrive near 23:00 to explore all three rooms and settle before the central Amsterdam ADE crowd reaches its peak.","crowd_mix":"Queer club kids, expressive dressers, techno and house dancers, performers and ADE visitors form the intentionally unconventional room.","dress_code":"Bold colour, creative makeup and fearless personal looks are strongly encouraged as the party's antidote to uniform dark techno styling.","host_inclusivity":"RARA AVIS explicitly calls itself a safe playground for queer people, with queer artists and freedom of expression central.","source_urls":["https://ra.co/events/2507060"],"research_status":"organiser_ticketing_times_and_queer_focus_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"MainStage Pride Amsterdam 2027","aliases":["MainStage Pride 2027"],"city":"amsterdam","date":"2027-07-30","start_date":"2027-07-30","end_date":"2027-08-01","description":"MainStage Pride returns to Dam Square for three days of LGBTQIA+ artists, DJs, drag and performance from 30 July–1 August 2027.","link":"https://mainstageprideamsterdam.nl/","ticket_url":"https://mainstageprideamsterdam.nl/","location":"Dam Square, 1012 NP Amsterdam, Netherlands","lat":52.3731,"lng":4.8926,"vibe":"huge open-air Pride stage joining drag, DJs, community and city-centre celebration","intel":{"entry_wait":"General admission is free, while Pride Deck tickets guarantee elevated access; small bags may be checked and large bags are prohibited.","best_arrival":"Reach Dam Square early each day for public capacity, or use the booked Pride Deck entry; Amsterdam Centraal is a short walk away.","crowd_mix":"Amsterdam LGBTQIA+ communities, international Pride visitors, drag audiences, families during eligible hours and allies attend.","dress_code":"Expressive Pride looks are welcome; prepare for changing weather and use comfortable footwear for standing on the square.","host_inclusivity":"The organiser publishes zero tolerance for discrimination, a welfare team, accessible toilets, sign interpretation and an Extra Care Deck.","source_urls":["https://mainstageprideamsterdam.nl/"],"research_status":"official_2027_dates_access_and_safety_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Kult Funktion – Rotterdam Pride","aliases":["Kult Funktion Rotterdam Pride 2026"],"city":"rotterdam","date":"2026-09-26","start_date":"2026-09-26","end_date":"2026-09-27","description":"Kult Funktion takes over export from 22:00–05:00 during Rotterdam Pride with house, a dance showcase and space for LGBTQIA+, BIPOC and women artists.","link":"https://ra.co/events/2485596","ticket_url":"https://ra.co/events/2485596","location":"export, Keilestraat 7E, 3029 BP Rotterdam, Netherlands","lat":51.9113,"lng":4.4327,"vibe":"forward-looking Pride house night combining representation, dance and community building","intel":{"entry_wait":"Advance tickets are listed at fourteen euros; bring valid 18+ identification and book ahead for the finite warehouse-style venue.","best_arrival":"Arrive around 22:00 to see the house-dance and ballroom elements as well as the complete musical build.","crowd_mix":"LGBTQIA+, BIPOC and women artists and communities are foregrounded alongside Rotterdam house dancers and Pride visitors.","dress_code":"No mandatory code is listed; expressive Pride clubwear and shoes suitable for house dancing fit the programme.","host_inclusivity":"Kult Funktion explicitly creates opportunities for LGBTQIA+, BIPOC and female artists and frames the floor around representation and connection.","source_urls":["https://ra.co/events/2485596"],"research_status":"organiser_ticketing_and_representation_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Queer Sunday Café – October 2026","aliases":["October Queer Events 010 x OASE Queer Sunday Cafe"],"city":"rotterdam","date":"2026-10-11","start_date":"2026-10-11","end_date":"2026-10-11","description":"Queer Events 010 and OASE host a relaxed Sunday café from 13:00 where queer people and allies can meet through conversation, activities and games.","link":"https://www.oaserotterdam.nl/programma","ticket_url":"https://www.oaserotterdam.nl/programma","location":"OASE, Schiehaven 15A, 3024 EC Rotterdam, Netherlands","lat":51.9054,"lng":4.4560,"vibe":"low-pressure queer community afternoon designed for conversation and new friendships","intel":{"entry_wait":"Entry starts from five euros through the venue programme; book if offered, though the drop-in format permits flexible arrival.","best_arrival":"Come near 13:00 to join the opening activities and introductions, or drop in later if a gentler social entry feels better.","crowd_mix":"Queer Rotterdam residents, newcomers, people attending alone and respectful allies meet in a deliberately easy-going environment.","dress_code":"There is no dress code; comfortable everyday clothing suits a daytime café focused on conversation rather than nightlife display.","host_inclusivity":"Queer Events 010 explicitly creates a welcoming community meeting place where queer people and allies can connect and belong.","source_urls":["https://www.oaserotterdam.nl/programma"],"research_status":"official_venue_schedule_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Queer Sunday Café – November 2026","aliases":["November Queer Events 010 x OASE Queer Sunday Cafe"],"city":"rotterdam","date":"2026-11-08","start_date":"2026-11-08","end_date":"2026-11-08","description":"Queer Events 010 and OASE return with a November Sunday café from 13:00, using activities, conversation and games to help queer people and allies connect.","link":"https://www.oaserotterdam.nl/programma","ticket_url":"https://www.oaserotterdam.nl/programma","location":"OASE, Schiehaven 15A, 3024 EC Rotterdam, Netherlands","lat":51.9054,"lng":4.4560,"vibe":"welcoming queer social afternoon with structured icebreakers and flexible drop-in access","intel":{"entry_wait":"The venue lists entry from five euros; use the programme ticket route if available, with the café designed for flexible drop-in participation.","best_arrival":"Arrive around 13:00 for the opening social structure, while later arrival remains possible for guests preferring a shorter visit.","crowd_mix":"Queer locals, newcomers, solo visitors and allies seeking friendship or community rather than a loud club environment attend.","dress_code":"No appearance rule applies; casual and comfortable daytime clothing is entirely appropriate for the relaxed café format.","host_inclusivity":"The collaboration explicitly welcomes queer people and allies and uses planned activities to lower barriers to meeting and belonging.","source_urls":["https://www.oaserotterdam.nl/programma"],"research_status":"official_venue_schedule_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Brussels Open Air: Fatma Sound System x FEMMEBASS x Nashaz","aliases":["Fatma Sound System X FEMMEBASS X Nashaz"],"city":"brussels","date":"2026-09-12","start_date":"2026-09-12","end_date":"2026-09-12","description":"Three collectives create a Vaux Hall safer space from 14:00–22:00 led by migrant, women, queer, trans and racialised communities across dub, house and percussion.","link":"https://www.visit.brussels/en/visitors/agenda/event-detail.Brussels-Open-Air-Festival-Fatma-Sound-System-X-FEMMEBASS-X-Nashaz.5700024963","ticket_url":"https://www.visit.brussels/en/visitors/agenda/event-detail.Brussels-Open-Air-Festival-Fatma-Sound-System-X-FEMMEBASS-X-Nashaz.5700024963","location":"Vaux Hall, Rue de la Loi 5, 1000 Brussels, Belgium","lat":50.8443,"lng":4.3646,"vibe":"open-air safer-space celebration moving diasporic sound and marginalised communities to the centre","intel":{"entry_wait":"Festival passes cover multiple city stages and capacity can vary; secure the relevant ticket and allow time for park security.","best_arrival":"Reach Vaux Hall near 14:00 to experience the full live, performance and DJ programme and orient yourself in daylight.","crowd_mix":"Migrants, women, queer, trans and racialised communities are centred with respectful Brussels music audiences welcomed.","dress_code":"No dress code is published; weather-ready expressive clothing and comfortable outdoor dance shoes are practical.","host_inclusivity":"The organisers explicitly call the event a safer space for underrepresented communities to gather, perform and celebrate their existence.","source_urls":["https://www.visit.brussels/en/visitors/agenda/event-detail.Brussels-Open-Air-Festival-Fatma-Sound-System-X-FEMMEBASS-X-Nashaz.5700024963"],"research_status":"official_dmo_schedule_and_safer_space_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Viciosa x Gelatina","aliases":["Viciosa Gelatina Brussels 2026"],"city":"brussels","date":"2026-09-26","start_date":"2026-09-26","end_date":"2026-09-27","description":"Viciosa and Gelatina open Les Halles de Schaerbeek's season with a queer-forward Latinx programme spanning reggaeton, hyperpop, drum and bass and club experimentation.","link":"https://www.visit.brussels/en/visitors/what-to-do/lgbtqia/the-events","ticket_url":"https://www.halles.be/","location":"Les Halles de Schaerbeek, Rue Royale Sainte-Marie 22A, 1030 Brussels, Belgium","lat":50.8632,"lng":4.3691,"vibe":"bold queer Latinx festival night connecting reggaeton, hyperpop and club futurism","intel":{"entry_wait":"Use Les Halles' official ticket route and check final doors and running order before travel because this is the season-opening programme.","best_arrival":"Arrive for the published opening rather than only the late club section to experience the full live and DJ progression.","crowd_mix":"Latinx and LGBTQ+ communities, Brussels club audiences and followers of experimental global pop and bass music meet here.","dress_code":"No mandatory appearance rule is published; bold, colourful and movement-ready clubwear fits the programme's creative energy.","host_inclusivity":"The line-up foregrounds LGBTQ+ voices and Latinx collectives, with community representation built into the programme rather than added as branding.","source_urls":["https://www.visit.brussels/en/visitors/what-to-do/lgbtqia/the-events","https://www.halles.be/"],"research_status":"official_dmo_programme_verified_queer_forward","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Los Ninos: Queer Berlin","aliases":["Los Ninos Queer Berlin 2026"],"city":"brussels","date":"2026-10-16","start_date":"2026-10-16","end_date":"2026-10-17","description":"Los Ninos brings a deliberately queer Berlin electronic programme to C12 from 23:00–06:00 with AAguilAA, DJ Handbag and Immy.","link":"https://ra.co/events/2489613","ticket_url":"https://ra.co/events/2489613","location":"C12, Rue du Marché aux Herbes 116, 1000 Brussels, Belgium","lat":50.8468,"lng":4.3547,"vibe":"Berlin-linked queer electronic night inside Brussels' central underground club","intel":{"entry_wait":"Advance tickets are listed from fourteen euros; bring valid 18+ identification and arrive before the central late-night queue peaks.","best_arrival":"Reach C12 near 23:00 for a smoother entry and the complete three-artist progression through the night.","crowd_mix":"Brussels queer clubbers, Los Ninos regulars, Berlin-scene followers and open-minded electronic dancers share the floor.","dress_code":"No mandatory look is listed; expressive queer clubwear and practical dance shoes suit C12's underground setting.","host_inclusivity":"The promoter explicitly frames this edition around Berlin's queer electronic offer rather than as a generic themed club night.","source_urls":["https://ra.co/events/2489613"],"research_status":"organiser_ticketing_and_queer_programme_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Fuse presents PACT","aliases":["PACT Joachim Pastor Joris Delacroix Teho"],"city":"brussels","date":"2026-09-19","start_date":"2026-09-19","end_date":"2026-09-20","description":"Fuse hosts PACT from 23:00–07:00 with melodic and progressive electronic sets under its no-phone, consent and zero-discrimination club policy.","link":"https://ra.co/events/2509862","ticket_url":"https://ra.co/events/2509862","location":"Fuse, Rue Blaes 208, 1000 Brussels, Belgium","lat":50.8360,"lng":4.3458,"vibe":"focused queer-friendly electronic night with privacy, care team and strict floor etiquette","intel":{"entry_wait":"A twenty-euro ticket does not guarantee admission; bring ID, dress for the club and allow time for the venue's values-led selection.","best_arrival":"Arrive near 23:00 for a calmer door and orientation before the headline programme and main-floor density build.","crowd_mix":"Melodic electronic listeners, Fuse regulars, queer-friendly dancers and international visitors share a music-focused audience.","dress_code":"Muted functional club clothing is required; suits, heels, sandals and flashy items are explicitly discouraged by the venue.","host_inclusivity":"Fuse bans racism, sexism, homophobia and transphobia, requires consent, tapes cameras and provides an identifiable Care Team.","source_urls":["https://ra.co/events/2509862"],"research_status":"organiser_ticketing_door_and_care_policy_verified_queer_friendly","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"WOEKER 2026","aliases":["WOEKER by Antwerp Queer Arts Festival"],"city":"antwerp","date":"2026-11-13","start_date":"2026-11-13","end_date":"2026-11-29","description":"Antwerp Queer Arts Festival and Genderspectrum launch WOEKER, a multi-city artistic and activist programme for trans, intersex, agender, non-binary and genderfluid artists.","link":"https://www.queerarts.be/","ticket_url":"https://www.queerarts.be/","location":"Antwerp and partner venues across Belgium","lat":51.2194,"lng":4.4025,"vibe":"trans-centred arts and activism platform unfolding through performance, memory and solidarity","intel":{"entry_wait":"Individual venues and performances will set their own booking rules; reserve limited sessions once the final multi-city programme is published.","best_arrival":"Plan by city and venue rather than treating WOEKER as one gate, and reach each event before its stated seating or start time.","crowd_mix":"Trans, intersex, agender, non-binary and genderfluid artists and audiences are centred alongside queer communities and allies.","dress_code":"There is no programme-wide dress code; practical cultural-event clothing works, with expressive looks welcome at performances.","host_inclusivity":"The platform explicitly centres gender-diverse artists during Transgender Awareness Week and around Transgender Day of Remembrance.","source_urls":["https://www.queerarts.be/","https://www.queerarts.be/open-call-woeker"],"research_status":"official_dates_scope_and_community_focus_verified","updated_at":"2026-08-29T00:00:00Z"}},
