{"name":"Unsound Warsaw 2026","aliases":["Unsound Warszawa 2026","Unsound Soft Power Warsaw"],"city":"warsaw","date":"2026-10-02","start_date":"2026-10-02","end_date":"2026-10-06","description":"Unsound's 2026 Soft Power edition begins in Warsaw with experimental electronics, club nights, performance and discourse before its dedicated festival train continues to Kraków.","link":"https://www.unsound.pl/en/2026/warszawa-krakow/news/unsound-2026-soft-power-in-krakow-and-warsaw-two-cities-one-festival-the-unsound-train","ticket_url":"https://ra.co/events/2474764","location":"Tunelowa, Jasna 1, OCZKI and multiple Warsaw venues, Poland","lat":52.2297,"lng":21.0122,"vibe":"adventurous electronic festival chapter mixing queer artists, experimentation and critical discourse","intel":{"entry_wait":"Passes and individual tickets differ, and a pass does not guarantee late seating or entry after free-event capacity is reached.","best_arrival":"Build a venue-by-venue schedule and arrive early for seated work; Warsaw-to-Kraków pass holders should separately confirm train instructions.","crowd_mix":"Experimental music listeners, queer and trans audiences, artists, international visitors and Polish club communities meet across formats.","dress_code":"There is no festival-wide code; practical layers and comfortable shoes work for movement between concert, discourse and club venues.","host_inclusivity":"Unsound's Mutual Respect policy explicitly protects diverse sexual orientations, gender expressions, non-binary and trans guests from discrimination.","source_urls":["https://www.unsound.pl/en/2026/warszawa-krakow/news/unsound-2026-soft-power-in-krakow-and-warsaw-two-cities-one-festival-the-unsound-train","https://www.unsound.pl/en/archive/pl/solidarity/mutual-respect.html","https://ra.co/events/2474764"],"research_status":"official_dates_ticketing_and_mutual_respect_verified_queer_friendly","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"SAY YES: Sekta Selekta Takeover","aliases":["SAY YES Sekta Selekta Takeover"],"city":"krakow","date":"2026-09-04","start_date":"2026-09-04","end_date":"2026-09-05","description":"SAY YES gives Kraków's Sekta Selekta to kEczuP, Kola and 4/4 from 22:00–06:00 for minimal and electronic music under an explicitly stated PLUR rule.","link":"https://ra.co/events/2514274","ticket_url":"https://ra.co/events/2514274","location":"Sekta Selekta, Nowa, 31-056 Kraków, Poland","lat":50.0517,"lng":19.9465,"vibe":"intimate queer-friendly minimal session guided by peace, love, unity and respect","intel":{"entry_wait":"Advance tickets are available and the listing quotes twenty to thirty złoty; buy before travel and bring valid identification.","best_arrival":"Arrive around 22:00 to find the small venue comfortably and hear the full takeover before the room reaches peak density.","crowd_mix":"Kraków underground regulars, minimal listeners, visiting scene followers and queer-friendly dancers gather in a compact setting.","dress_code":"No formal appearance requirement is stated; relaxed, movement-ready underground clubwear fits the music-first night.","host_inclusivity":"The organiser publishes PLUR—peace, love, unity and respect—as the event rule; this is queer-friendly rather than queer-exclusive.","source_urls":["https://ra.co/events/2514274"],"research_status":"organiser_ticketing_and_plur_rule_verified_queer_friendly","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Unsound Kraków 2026","aliases":["Unsound Krakow 2026","Unsound Soft Power Krakow"],"city":"krakow","date":"2026-10-08","start_date":"2026-10-08","end_date":"2026-10-11","description":"Unsound's Soft Power journey reaches Kraków for concerts, discourse and three large experimental club nights across Hotel Forum and city venues.","link":"https://www.unsound.pl/en/2026/warszawa-krakow","ticket_url":"https://ra.co/events/2474764","location":"Hotel Forum and multiple Kraków venues, Poland","lat":50.0488,"lng":19.9315,"vibe":"boundary-pushing electronic festival finale with queer artistry and explicit mutual-respect principles","intel":{"entry_wait":"Kraków, club and full-festival passes cover different events; free capacity and seated sessions are not guaranteed for late arrivals.","best_arrival":"Use the detailed timetable and reach Hotel Forum before the 21:30 club openings, leaving time to navigate its three performance rooms.","crowd_mix":"Experimental electronic audiences, queer and trans guests, artists, students and international festival travellers share the programme.","dress_code":"No mandatory code applies; practical dancewear, layers and comfortable footwear suit long nights in the brutalist Hotel Forum complex.","host_inclusivity":"Unsound's Mutual Respect programme explicitly seeks safety from discrimination for diverse sexualities, gender expressions, non-binary and trans people.","source_urls":["https://www.unsound.pl/en/2026/warszawa-krakow","https://www.unsound.pl/en/archive/pl/solidarity/mutual-respect.html","https://ra.co/events/2474764","https://ra.co/events/2520242"],"research_status":"official_dates_venues_ticketing_and_mutual_respect_verified","updated_at":"2026-08-29T00:00:00Z"}}
]
$qa_central_europe_batch3_events$) e(
  name text, aliases jsonb, city text, date date, start_date date, end_date date,
  description text, link text, ticket_url text, location text,
  lat double precision, lng double precision, vibe text, intel jsonb
  )
), matched as (
  select s.*, existing.id as existing_id
  from src s
  left join lateral (
    select candidate.id
    from public.events candidate
    where lower(trim(candidate.city)) = lower(trim(s.city))
      and (
        lower(regexp_replace(trim(candidate.name), '[^a-z0-9]+', '', 'gi')) = lower(regexp_replace(trim(s.name), '[^a-z0-9]+', '', 'gi'))
        or exists (
          select 1 from jsonb_array_elements_text(coalesce(s.aliases, '[]'::jsonb)) alias_name
          where lower(regexp_replace(trim(candidate.name), '[^a-z0-9]+', '', 'gi')) = lower(regexp_replace(trim(alias_name), '[^a-z0-9]+', '', 'gi'))
        )
        or (
          candidate.start_date = s.start_date and nullif(trim(candidate.link), '') is not null
          and lower(trim(candidate.link)) in (lower(trim(s.link)), lower(trim(coalesce(s.ticket_url, s.link))))
        )
      )
    order by case when lower(trim(candidate.name)) = lower(trim(s.name)) then 0 else 1 end,
      candidate.updated_at desc nulls last
    limit 1
  ) existing on true
), updated as (
  update public.events target
  set name=m.name, description=m.description, link=m.link, ticket_url=m.ticket_url,
      date=m.date, start_date=m.start_date, end_date=m.end_date, location=m.location,
      lat=m.lat, lng=m.lng, vibe=m.vibe, vibe_tags=array[]::text[], event_intel=m.intel,
      seo_indexable=true, seo_quality_status='approved', updated_at=timezone('utc', now())
  from matched m where target.id=m.existing_id returning target.id
)
insert into public.events(
  name, city, description, link, ticket_url, date, start_date, end_date,
  location, lat, lng, vibe, vibe_tags, event_intel,
  seo_indexable, seo_quality_status, updated_at
)
select name, city, description, link, ticket_url, date, start_date, end_date,
  location, lat, lng, vibe, array[]::text[], intel,
  true, 'approved', timezone('utc', now())
from matched where existing_id is null;

do $qa_no_central_europe_batch3_duplicates$
begin
  if exists (
    select 1 from public.events
    where start_date >= date '2026-08-29' and event_intel->>'updated_at'='2026-08-29T00:00:00Z'
    group by lower(trim(city)), lower(regexp_replace(trim(name), '[^a-z0-9]+', '', 'gi')), start_date
    having count(*) > 1
  ) then
    raise exception 'Central Europe Batch 3 duplicate detected; transaction rolled back.';
  end if;
end;
$qa_no_central_europe_batch3_duplicates$;

commit;
